// PRD #4208 M1: worker_hibernation_inventories (migration 00448).
// Every write to worker_hibernation_inventories runs in a transaction that already holds the
// workers row lock (GetWorkerForUpdate); lock order workers -> inventory. The reads below that
// take a worker-id list are batched and unlocked: they feed the dry-run report, which only
// reports and never deletes anything.
// ---------------------------------------------------------------------------
// Start (or restart) the inventory for the worker's current op: every column is replaced and the
// inventory and validity columns are NULLed, so a new op never inherits an older op's entries.
func (q *Queries) UpsertHibernationInventoryObserved(ctx context.Context, arg UpsertHibernationInventoryObservedParams) (WorkerHibernationInventory, error) {
	row := q.db.QueryRow(ctx, upsertHibernationInventoryObserved,
		arg.WorkerID,
		arg.OpID,
		arg.ObservedAt,
		arg.DeploymentUid,
		arg.DeploymentResourceVersion,
		arg.PodUid,
		arg.Pvcs,
		arg.Status,
	)
	var i WorkerHibernationInventory
	err := row.Scan(
		&i.WorkerID,
		&i.OpID,
		&i.ObservedAt,
		&i.DeploymentUid,
		&i.DeploymentResourceVersion,
		&i.PodUid,
		&i.Pvcs,
		&i.RegisterNonce,
		&i.ReceivedAt,
		&i.Status,
		&i.StatusReason,
		&i.Complete,
		&i.Entries,
		&i.ReceiptKeys,
		&i.Digest,
		&i.Fingerprint,
		&i.Lane,
		&i.Mechanism,
		&i.InvalidatedReason,
		&i.InvalidatedAt,
		&i.ScalingDownPodUid,
		&i.FenceGeneration,
		&i.ScaledDownAt,
		&i.LastHeldAt,
		&i.ExclusionFinalAt,
		&i.ExclusionFinalDigest,
		&i.ExclusionFinalFingerprint,
	)
	return i, err
}

const workerHasOpenCustodyHold = `-- name: WorkerHasOpenCustodyHold :one
SELECT EXISTS (
    SELECT 1 FROM recovery_custody_holds h
    WHERE h.live_worker_id = $1 AND h.state = 'open'
)::boolean
`

// The same predicate as ListHostedWorkersForController's custody_held column.
func (q *Queries) WorkerHasOpenCustodyHold(ctx context.Context, workerID pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, workerHasOpenCustodyHold, workerID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const workerHasPendingWakeDemand = `-- name: WorkerHasPendingWakeDemand :one
SELECT EXISTS (
    SELECT 1 FROM hibernation_wakes hw
    JOIN runs r ON r.id = hw.run_id
    WHERE hw.worker_id = $1 AND r.status = 'queued'
)::boolean AS pending
`

// Hibernate admission (PRD #4205 M5): true iff a queued run has a recorded wake naming this worker.
// Such a run woke the worker and is still waiting for it, so hibernating again would strand the run
// (its row suppresses a second wake). Read after the worker lock.
func (q *Queries) WorkerHasPendingWakeDemand(ctx context.Context, workerID uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, workerHasPendingWakeDemand, workerID)
	var pending bool
	err := row.Scan(&pending)
	return pending, err
}

